import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function invalid() {
  return Object.assign(new Error('Invalid batch'), { code: 'ERR_INVALID_BATCH' });
}

function conflict() {
  return Object.assign(new Error('Batch ID already used'), { code: 'ERR_BATCH_CONFLICT' });
}

function corrupt(message) {
  return Object.assign(new Error(message), { code: 'ERR_LEDGER_CORRUPT' });
}

function validate(batch) {
  if (!batch || typeof batch.id !== 'string' || !batch.id || !Array.isArray(batch.entries)) throw invalid();
  const entries = [];
  for (const entry of batch.entries) {
    if (!entry || typeof entry !== 'object') throw invalid();
    const { key, delta } = entry;
    if (typeof key !== 'string' || !KEY.test(key) || !Number.isSafeInteger(delta)) throw invalid();
    // `+ 0` normalizes -0 so in-memory results match their JSON round trip.
    entries.push({ key, delta: delta + 0 });
  }
  return { id: batch.id, entries };
}

function files(directory) {
  return {
    ledger: path.join(directory, 'ledger.json'),
    ledgerTmp: path.join(directory, 'ledger.tmp'),
    pending: path.join(directory, 'pending.json'),
    pendingTmp: path.join(directory, 'pending.tmp'),
  };
}

async function read(io, file, fallback) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error?.code === 'ENOENT') return fallback; throw error; }
  return JSON.parse(text);
}

// Stage to a temporary file, then atomically replace the target. A failed or
// partial staging write never affects the target file.
async function save(io, tmp, target, value) {
  await io.writeFile(tmp, JSON.stringify(value));
  await io.rename(tmp, target);
}

async function removePending(io, f) {
  try { await io.unlink(f.pending); }
  catch (error) { if (error?.code !== 'ENOENT') throw error; }
}

function apply(state, batch) {
  const balances = { ...state.balances };
  for (const { key, delta } of batch.entries) {
    const value = (Object.hasOwn(balances, key) ? balances[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) throw invalid();
    balances[key] = value;
  }
  return { revision: state.revision + 1, balances, receipts: [...state.receipts, batch] };
}

function hasReceipt(state, id) {
  return state.receipts.some(item => item.id === id);
}

// Reads durable state without writing. Returns the committed snapshot and the
// remaining recovery work for a pending transaction, if any.
async function load(io, f) {
  const ledger = await read(io, f.ledger, { revision: 0, balances: {}, receipts: [] });
  const pending = await read(io, f.pending, null);
  if (!pending) return { state: ledger, publish: false, cleanup: false };
  if (hasReceipt(ledger, pending.id)) return { state: ledger, publish: false, cleanup: true };
  if (ledger.revision !== pending.base) throw corrupt('Pending transaction does not match ledger revision');
  return { state: pending.next, publish: true, cleanup: true };
}

async function finish(io, f, { state, publish, cleanup }) {
  if (publish) await save(io, f.ledgerTmp, f.ledger, state);
  if (cleanup) await removePending(io, f);
}

export async function recoverLedger(directory, { io = fs } = {}) {
  const f = files(directory);
  await io.mkdir(directory, { recursive: true });
  const loaded = await load(io, f);
  await finish(io, f, loaded);
  return loaded.state;
}

export async function commitBatch(directory, batch, { io = fs, checkpoint } = {}) {
  batch = validate(batch);
  const f = files(directory);
  await io.mkdir(directory, { recursive: true });
  const loaded = await load(io, f);
  const { state } = loaded;

  const receipt = state.receipts.find(item => item.id === batch.id);
  if (receipt) {
    if (JSON.stringify(receipt.entries) !== JSON.stringify(batch.entries)) throw conflict();
    await finish(io, f, loaded);
    return state;
  }
  // Validate the result before any durable change, including earlier recovery.
  const next = apply(state, batch);

  await finish(io, f, loaded);
  // The pending record holds the full final snapshot, so recovery can publish
  // it without the original caller.
  await save(io, f.pendingTmp, f.pending, { id: batch.id, base: state.revision, next });
  if (checkpoint) await checkpoint('prepared');
  await save(io, f.ledgerTmp, f.ledger, next);
  if (checkpoint) await checkpoint('published');
  await removePending(io, f);
  if (checkpoint) await checkpoint('complete');
  return next;
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { commitBatch, recoverLedger } from './src/ledger.js';

const a = { id: 'a', entries: [{ key: 'cash', delta: 5 }, { key: 'bank', delta: -2 }] };
const b = { id: 'b', entries: [{ key: 'cash', delta: 3 }, { key: 'cash', delta: 1 }] };
const expected = { revision: 2, balances: { cash: 9, bank: -2 }, receipts: [a, b] };

function faulty(failAt, mode) {
  let n = 0;
  const wrap = name => async (...args) => {
    if (n++ === failAt) {
      if (mode === 'partial' && name === 'writeFile') await fs.writeFile(args[0], String(args[1]).slice(0, 7));
      if (mode === 'after' && name !== 'writeFile') { await fs[name](...args); }
      throw Object.assign(new Error(`fault ${name}`), { code: 'EIO' });
    }
    return fs[name](...args);
  };
  return { io: Object.fromEntries(['mkdir', 'readFile', 'writeFile', 'rename', 'unlink'].map(k => [k, wrap(k)])), count: () => n };
}

let cases = 0;
for (const mode of ['before', 'partial']) {
  for (let failAt = 0; failAt < 40; failAt++) {
    for (const how of ['retry', 'recover']) {
      const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sweep-'));
      await commitBatch(dir, a);
      const f = faulty(failAt, mode);
      let failed = false;
      try { await commitBatch(dir, b, { io: f.io }); } catch (e) { failed = true; assert.equal(e.code, 'EIO'); }
      if (!failed && failAt >= f.count()) { await fs.rm(dir, { recursive: true }); continue; }
      if (how === 'recover') await recoverLedger(dir);
      assert.deepEqual(await commitBatch(dir, b), expected, `${mode} ${failAt} ${how}`);
      assert.deepEqual(await recoverLedger(dir), expected);
      const left = (await fs.readdir(dir)).filter(x => x.endsWith('.json'));
      assert.deepEqual(left.sort(), ['ledger.json']);
      await fs.rm(dir, { recursive: true });
      cases++;
    }
  }
}

for (const phase of ['prepared', 'published', 'complete']) {
  for (const how of ['retry', 'recover', 'other']) {
    const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sweep-'));
    await commitBatch(dir, a);
    const seen = [];
    const err = new Error('stop');
    await assert.rejects(commitBatch(dir, b, { checkpoint: async p => { seen.push(p); if (p === phase) throw err; } }), e => e === err);
    if (how === 'retry') assert.deepEqual(await commitBatch(dir, b), expected);
    if (how === 'recover') assert.deepEqual(await recoverLedger(dir), expected);
    if (how === 'other') {
      const c = { id: 'c', entries: [] };
      const got = await commitBatch(dir, c);
      assert.deepEqual(got, { ...expected, revision: 3, receipts: [a, b, c] });
      await assert.rejects(commitBatch(dir, { id: 'b', entries: [] }), e => e.code === 'ERR_BATCH_CONFLICT');
    } else {
      assert.deepEqual(await recoverLedger(dir), expected);
    }
    await fs.rm(dir, { recursive: true });
    cases++;
  }
}

